using System;using System.Collections.Generic;using UnityEngine;
namespace Vanta.Missions{public sealed class MissionSystem:MonoBehaviour{public enum Status{Inactive,Active,Complete,Failed}[Serializable]public sealed class RuntimeMission{public string id;public Status status;public int objectiveIndex;}readonly Dictionary<string,RuntimeMission> missions=new();public event Action<string,Status> StatusChanged;public Status GetStatus(string id)=>missions.TryGetValue(id,out var m)?m.status:Status.Inactive;public void StartMission(MissionDefinition def){if(!def)return;missions[def.missionId]=new RuntimeMission{id=def.missionId,status=Status.Active};StatusChanged?.Invoke(def.missionId,Status.Active);}public void CompleteMission(string id){if(!missions.TryGetValue(id,out var m)||m.status!=Status.Active)return;m.status=Status.Complete;StatusChanged?.Invoke(id,m.status);}public void FailMission(string id){if(!missions.TryGetValue(id,out var m)||m.status!=Status.Active)return;m.status=Status.Failed;StatusChanged?.Invoke(id,m.status);}}}